package com.tura.ventas.service;
import java.math.*; import java.time.LocalDate; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.tura.ventas.exception.NegocioException; import com.tura.ventas.modelo.*; import com.tura.ventas.repositorio.*;
@Service public class VentaService {
 private final VentaRepository vr; private final ClienteRepository cr; private final ProductoRepository pr; private final VentaCabeceraRepository vcr;
 public VentaService(VentaRepository vr,ClienteRepository cr,ProductoRepository pr,VentaCabeceraRepository vcr){this.vr=vr;this.cr=cr;this.pr=pr;this.vcr=vcr;}
 public List<Venta> listar(){return vr.listarDetalle();} public Venta obtener(Integer id){return vr.findById(id).orElseThrow();} public List<Venta> filtrar(LocalDate d,LocalDate h,Integer c){return vr.filtrar(d,h,c);} public List<Object[]> resumen(){return vr.resumenPorProducto();} public List<VentaCabecera> listarCabeceras(){return vcr.listarCompleto();} public long contar(){return vcr.count()>0?vcr.count():vr.count();}
 public record Linea(Integer productoId,int cantidad){}
 @Transactional public VentaCabecera registrarCabecera(String numero,Integer clienteId,String ruc,Integer moneda,LocalDate fecha,List<Linea> lineas){
  if(numero==null||numero.isBlank())throw new NegocioException("El número de venta es obligatorio."); if(lineas==null||lineas.isEmpty())throw new NegocioException("Agregue al menos un producto al detalle.");
  Cliente c=cr.findById(clienteId).orElseThrow(()->new NegocioException("Cliente no encontrado.")); VentaCabecera cab=new VentaCabecera(); cab.setNumero(numero.trim()); cab.setCliente(c); cab.setRuc(ruc==null||ruc.isBlank()?c.getRuc():ruc.trim()); cab.setMoneda(moneda==null?1:moneda);
  BigDecimal subtotal=BigDecimal.ZERO; LocalDate f=fecha==null?LocalDate.now():fecha;
  for(Linea linea:lineas){if(linea.productoId()==null||linea.cantidad()<=0)throw new NegocioException("Cada línea debe tener producto y cantidad mayor que cero."); Producto p=pr.findById(linea.productoId()).orElseThrow(()->new NegocioException("Producto no encontrado.")); if(p.getStockActual()<linea.cantidad())throw new NegocioException("Stock insuficiente para "+p.getNombre()+". Disponible: "+p.getStockActual()); Venta det=new Venta(); det.setCabecera(cab);det.setCliente(c);det.setProducto(p);det.setCantidad(linea.cantidad());det.setPrecio(p.getPrecio());det.setFecha(f);cab.getDetalles().add(det);subtotal=subtotal.add(p.getPrecio().multiply(BigDecimal.valueOf(linea.cantidad())));p.setStockActual(p.getStockActual()-linea.cantidad());pr.save(p);}
  BigDecimal igv=subtotal.multiply(new BigDecimal("0.18")).setScale(5,RoundingMode.HALF_UP);cab.setSubtotalAfecto(subtotal.setScale(5,RoundingMode.HALF_UP));cab.setTotalNoAfecto(BigDecimal.ZERO.setScale(5));cab.setIgv(igv);cab.setTotal(subtotal.add(igv).setScale(5,RoundingMode.HALF_UP));return vcr.save(cab);
 }
 @Transactional public Venta registrar(Integer clienteId,Integer productoId,int cantidad,LocalDate fecha){VentaCabecera c=registrarCabecera("WEB-"+System.currentTimeMillis(),clienteId,null,1,fecha,List.of(new Linea(productoId,cantidad)));return c.getDetalles().get(0);}
 @Transactional public void eliminarCabecera(Integer id){VentaCabecera cab=vcr.obtenerCompleto(id).orElseThrow(()->new NegocioException("Venta no encontrada."));for(Venta d:new ArrayList<>(cab.getDetalles())){Producto p=d.getProducto();p.setStockActual(p.getStockActual()+d.getCantidad());pr.save(p);}vcr.delete(cab);}
 @Transactional public void eliminar(Integer id){Venta v=vr.findById(id).orElseThrow(()->new NegocioException("Detalle de venta no encontrado."));if(v.getCabecera()!=null){eliminarCabecera(v.getCabecera().getIdventac());return;}Producto p=v.getProducto();p.setStockActual(p.getStockActual()+v.getCantidad());pr.save(p);vr.delete(v);}
}
